        for trix = 1:nTrials
            x = squeeze(xpos{view}(:,trix,feat));
            y = squeeze(ypos{view}(:,trix,feat));
            vis.mask = logical(sum(~isnan(x),2)); % just need either visibile in x or y

            istart = ZeroOnesCount(vis.mask);


            xstart = x(istart,:);
